import { Easing, Interactive, Sequence, interpolate, useCurrentFrame, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";
import { forwardRef, useImperativeHandle, useRef, type ComponentProps } from "react";

interface ShortSlideRightProps {
  text: string;
  distance?: number;
  staggerDelay?: number;
  fontSize?: number;
  color?: string;
  fontWeight?: number;
  speed?: number;
  className?: string;
}

function ShortSlideRightBase({
  text,
  distance = 24,
  staggerDelay = 3,
  fontSize = 72,
  color = "#171717",
  fontWeight = 600,
  speed = 1,
  className,
}: ShortSlideRightProps) {
  const frame = useCurrentFrame() * speed;

  const words = text.split(" ");

  const enterDur = 16;
  const travelDur = 8;
  const wordOpacityDur = 6;
  const easing = Easing.bezier(0.2, 0.8, 0.2, 1);

  const x = interpolate(frame, [0, travelDur], [-distance, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing,
  });

  const blurVal = interpolate(frame, [0, enterDur], [1.2, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing,
  });

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        background: "transparent",
      }}
    >
      <span
        className={className}
        style={{
          fontSize,
          fontWeight,
          color,
          letterSpacing: "-0.03em",
          fontFamily:
            "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif",
          display: "inline-block",
          translate: `${x}px`,
          filter: `blur(${blurVal}px)`,
        }}
      >
        {words.map((word, i) => {
          const opacity = interpolate(
            frame - i * staggerDelay,
            [0, wordOpacityDur],
            [0, 1],
            {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
              easing,
            },
          );
          return (
            <span
              key={i}
              style={{
                display: "inline-block",
                marginRight: "0.25em",
                opacity,
              }}
            >
              {word}
            </span>
          );
        })}
      </span>
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  text: {
    type: "text-content",
    default: "Move with intent.",
    description: "Text",
  },
  distance: {
    type: "number",
    min: 0,
    max: 120,
    step: 1,
    default: 24,
    description: "Distance",
    hiddenFromList: false,
  },
  staggerDelay: {
    type: "number",
    min: 0,
    max: 12,
    step: 1,
    default: 3,
    description: "Stagger",
    hiddenFromList: false,
  },
  fontSize: {
    type: "number",
    min: 12,
    max: 160,
    step: 1,
    default: 72,
    description: "Font size",
    hiddenFromList: false,
  },
  color: {
    type: "color",
    default: "#171717",
    description: "Color",
  },
  fontWeight: {
    type: "enum",
    default: "600",
    variants: {
      "400": {},
      "500": {},
      "600": {},
      "700": {},
    },
    description: "Font weight",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  width: {
    type: "number",
    default: 640,
    min: 10,
    step: 10,
    description: "Width",
  },
  height: {
    type: "number",
    default: 100,
    min: 10,
    step: 10,
    description: "Height",
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["text","distance","staggerDelay","fontSize","color","fontWeight","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  text: "Move with intent.",
  distance: 24,
  staggerDelay: 3,
  fontSize: 72,
  color: "#171717",
  fontWeight: "600",
  speed: 1,
};

type ShortSlideRightElementProps = InteractiveBaseProps &
  InteractiveTransformProps & { readonly width?: number; readonly height?: number } &
  ComponentProps<typeof ShortSlideRightBase>;

const ShortSlideRightInner = forwardRef<
  HTMLDivElement,
  ShortSlideRightElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, width = 640, height = 100, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ShortSlideRight>"}
      outlineRef={outlineRef}
    >
      <div
        style={{
          position: "absolute",
          inset: 0,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <div
          ref={outlineRef}
          style={{
            position: "relative",
            width,
            height,
            ...style,
          }}
        >
          <ShortSlideRightBase
            {...(componentProps as unknown as ComponentProps<typeof ShortSlideRightBase>)}
          />
        </div>
      </div>
    </Sequence>
  );
});

export const ShortSlideRight = Interactive.withSchema({
  Component: ShortSlideRightInner,
  componentName: "<ShortSlideRight>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
